import{_ as d,o as a,c as r,ag as e}from"./chunks/framework.CtWPcAmt.js";const g=JSON.parse('{"title":"第 23 章：终章——一份 30 天实践计划","description":"四周路线图（三个小任务 → 任务卡与验收 → 模板与 Skill → Harness 与复盘），把前 22 章变成 30 天行动；最终产出个人 Agent 使用手册 1.0。","frontmatter":{"title":"第 23 章：终章——一份 30 天实践计划","description":"四周路线图（三个小任务 → 任务卡与验收 → 模板与 Skill → Harness 与复盘），把前 22 章变成 30 天行动；最终产出个人 Agent 使用手册 1.0。","layout":"doc","lastUpdated":true},"headers":[],"relativePath":"guide/23-30day-plan.md","filePath":"guide/23-30day-plan.md","lastUpdated":null}'),l={name:"guide/23-30day-plan.md"};function i(o,t,n,h,s,b){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="第-23-章-终章——一份-30-天实践计划" tabindex="-1">第 23 章：终章——一份 30 天实践计划 <a class="header-anchor" href="#第-23-章-终章——一份-30-天实践计划" aria-label="Permalink to &quot;第 23 章：终章——一份 30 天实践计划&quot;">​</a></h1><h2 id="本章解决什么问题" tabindex="-1">本章解决什么问题 <a class="header-anchor" href="#本章解决什么问题" aria-label="Permalink to &quot;本章解决什么问题&quot;">​</a></h2><p>读到这里，你有了任务卡、权限表、验收清单、模板、Skill、规则和 Harness 草图——但它们还是「零件」。本章给你一份<strong>30 天组装计划</strong>：每周一个目标、每天一个动作，把这些零件组装成<strong>个人 Agent 使用手册 1.0</strong>。读完就能动手，不用再回来翻书找步骤（本书每章末尾的「你应该带走的成果」就是手册的目录）。</p><h2 id="从一个真实场景开始" tabindex="-1">从一个真实场景开始 <a class="header-anchor" href="#从一个真实场景开始" aria-label="Permalink to &quot;从一个真实场景开始&quot;">​</a></h2><p>大多数人学完教程后的两种结局：一种「懂了但没做」，三个月后全忘；一种「想全做」，第一周就把自己累趴，放弃。<strong>30 天计划解决的是「节奏」</strong>：每天 20–30 分钟，每周一个明确主题，第 4 周结束时你已经有一个能用的系统——而不是一本读完的理论书。</p><h2 id="先说结论" tabindex="-1">先说结论 <a class="header-anchor" href="#先说结论" aria-label="Permalink to &quot;先说结论&quot;">​</a></h2><ol><li><strong>30 天 = 4 周 × 1 个主题</strong>：第 1 周跑通任务、第 2 周稳定流程、第 3 周沉淀资产、第 4 周系统化；</li><li><strong>每天 20–30 分钟即可</strong>，重点是「连续做」，不是「一次做完」；</li><li><strong>全部使用你自己的真实任务</strong>（序章的任务种子），不学虚构例子；</li><li><strong>每周有一个「验收物」</strong>：3 个成功任务、稳定的任务卡与验收流程、模板与 Skill、Harness 与手册；</li><li><strong>30 天后你拥有的不是知识，是一套每天在用的系统</strong>。</li></ol><h2 id="_30-天路线图" tabindex="-1">30 天路线图 <a class="header-anchor" href="#_30-天路线图" aria-label="Permalink to &quot;30 天路线图&quot;">​</a></h2><h3 id="第-1-周-完成三个低风险小任务-对应第-1–4、7-章" tabindex="-1">第 1 周：完成三个低风险小任务（对应第 1–4、7 章） <a class="header-anchor" href="#第-1-周-完成三个低风险小任务-对应第-1–4、7-章" aria-label="Permalink to &quot;第 1 周：完成三个低风险小任务（对应第 1–4、7 章）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>天</th><th>动作</th><th>产出</th></tr></thead><tbody><tr><td>D1</td><td>读第 1、2 章，画 Agent 工作流程图，给任务定级</td><td>流程图 + L1–L4 等级</td></tr><tr><td>D2</td><td>读第 4 章，完成需求卡，选出 1 款产品</td><td>需求卡 + 候选</td></tr><tr><td>D3</td><td>安装/登录产品，熟悉界面（对照第 5 章对应产品页）</td><td>能打开、能发任务</td></tr><tr><td>D4</td><td>读第 7 章，把任务种子写成任务卡</td><td>第一张任务卡</td></tr><tr><td>D5</td><td>用任务卡跑第一个真实小任务（L1 低风险）</td><td>第一次成功交付</td></tr><tr><td>D6</td><td>读第 8 章，给任务建目录 + 权限卡 + 备份</td><td>权限卡 + 备份</td></tr><tr><td>D7</td><td>复盘本周：完成 2–3 个小任务；写复盘记录</td><td>3 个成功任务</td></tr></tbody></table><p><strong>周验收</strong>：完成 3 个低风险小任务（哪怕其中 1 个是「整理收藏夹」），全部有任务卡与记录。</p><h3 id="第-2-周-稳定任务卡与验收流程-对应第-9–11-章" tabindex="-1">第 2 周：稳定任务卡与验收流程（对应第 9–11 章） <a class="header-anchor" href="#第-2-周-稳定任务卡与验收流程-对应第-9–11-章" aria-label="Permalink to &quot;第 2 周：稳定任务卡与验收流程（对应第 9–11 章）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>天</th><th>动作</th><th>产出</th></tr></thead><tbody><tr><td>D8</td><td>读第 9 章，设监督档位与过程记录表</td><td>过程检查清单</td></tr><tr><td>D9</td><td>跑任务，练习「分段确认」与「接管」</td><td>一次带监督的执行</td></tr><tr><td>D10</td><td>读第 10 章，用验收清单验收</td><td>第一份验收记录</td></tr><tr><td>D11</td><td>用「修正反馈」修改 Agent 产物</td><td>一次成功返工</td></tr><tr><td>D12</td><td>读第 11 章，建 CONTEXT.md</td><td>项目上下文清单</td></tr><tr><td>D13</td><td>用 CONTEXT.md 跑一次任务</td><td>上下文不丢的任务</td></tr><tr><td>D14</td><td>复盘：把任务卡/验收清单各迭代到 v2</td><td>稳定模板</td></tr></tbody></table><p><strong>周验收</strong>：同一类任务连跑 2 次，格式一致、验收通过、不返工。</p><h3 id="第-3-周-建立模板与一个-skill-对应第-12–14-章" tabindex="-1">第 3 周：建立模板与一个 Skill（对应第 12–14 章） <a class="header-anchor" href="#第-3-周-建立模板与一个-skill-对应第-12–14-章" aria-label="Permalink to &quot;第 3 周：建立模板与一个 Skill（对应第 12–14 章）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>天</th><th>动作</th><th>产出</th></tr></thead><tbody><tr><td>D15</td><td>读第 12 章，盘点高频任务</td><td>3 个模板候选</td></tr><tr><td>D16</td><td>写任务卡模板 + 验收清单模板</td><td>2 个模板</td></tr><tr><td>D17</td><td>写 1 个输出格式模板并用起来</td><td>第 3 个模板</td></tr><tr><td>D18</td><td>读第 13 章，把最高频任务做成最小 Skill</td><td>第一个 Skill</td></tr><tr><td>D19</td><td>真实调用 Skill 并迭代 v1.1</td><td>Skill 稳定可用</td></tr><tr><td>D20</td><td>读第 14 章，写全局安全底线 + 项目规则</td><td>协作约定</td></tr><tr><td>D21</td><td>复盘：清理记忆/规则，更新模板</td><td>规则集 v1</td></tr></tbody></table><p><strong>周验收</strong>：3 个模板 + 1 个 Skill + 1 份协作约定，全部真实用过。</p><h3 id="第-4-周-画出-harness-并完成一次系统复盘-对应第-15–18、19–23-章" tabindex="-1">第 4 周：画出 Harness 并完成一次系统复盘（对应第 15–18、19–23 章） <a class="header-anchor" href="#第-4-周-画出-harness-并完成一次系统复盘-对应第-15–18、19–23-章" aria-label="Permalink to &quot;第 4 周：画出 Harness 并完成一次系统复盘（对应第 15–18、19–23 章）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>天</th><th>动作</th><th>产出</th></tr></thead><tbody><tr><td>D22</td><td>读第 15 章，画 Harness 草图</td><td>七要素草图</td></tr><tr><td>D23</td><td>读第 16 章，填六层设计表</td><td>最小 Harness 设计表</td></tr><tr><td>D24</td><td>按设计表补齐空缺层（先验证层）</td><td>Harness 落地</td></tr><tr><td>D25</td><td>读第 17 章，做一次双 Agent 实验（可选）</td><td>实验记录</td></tr><tr><td>D26</td><td>读第 18 章，跑一次改进循环</td><td>改进清单</td></tr><tr><td>D27</td><td>浏览第 19–22 章案例，对照自己的任务</td><td>案例对照笔记</td></tr><tr><td>D28</td><td>汇总手册：把各周产出整理成文档</td><td>手册 1.0 草稿</td></tr><tr><td>D29</td><td>手册评审：对照本书各章「应带走成果」查漏</td><td>手册 1.0</td></tr><tr><td>D30</td><td>用手册完成一个完整任务，正式启用</td><td>手册 1.0 发布</td></tr></tbody></table><p><strong>周验收</strong>：Harness 设计表填完 + 手册 1.0 成稿 + 用它完成一个完整任务。</p><h2 id="一个完整示例-第-1-周的「最小闭环」长什么样" tabindex="-1">一个完整示例（第 1 周的「最小闭环」长什么样） <a class="header-anchor" href="#一个完整示例-第-1-周的「最小闭环」长什么样" aria-label="Permalink to &quot;一个完整示例（第 1 周的「最小闭环」长什么样）&quot;">​</a></h2><ul><li>任务种子：整理旅行照片（低风险、材料齐、规则明确 → L1）；</li><li>任务卡：目标（按日期/地点整理 200 张照片，重复照片移到待删除）；材料（<code>photos/</code>）；约束（只读原图、输出到 <code>output/</code> 的整理方案文档）；交付物（整理方案 + 目录清单）；验收（覆盖全部照片、重复清单可核对）；</li><li>执行：Agent 生成方案 → 人按方案执行移动（或让 Agent 在 L1 权限下生成「建议命令」）；</li><li>验收：核对清单、检查有没有动原图；</li><li>复盘：沉淀「素材整理」任务卡模板（第 2 周直接用）。</li></ul><p><strong>注意：即使是「低风险」，移动文件也要先备份（第 8 章）；照片整理这类任务，建议用「先生成方案、人执行移动」的安全模式。</strong></p><h2 id="常见错误与恢复方法" tabindex="-1">常见错误与恢复方法 <a class="header-anchor" href="#常见错误与恢复方法" aria-label="Permalink to &quot;常见错误与恢复方法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>可能原因</th><th>怎样修正</th></tr></thead><tbody><tr><td>第 1 周就贪多</td><td>想一次学完</td><td>只做本周主题，其余章节存书签</td></tr><tr><td>没连续做，中断了</td><td>任务太难/太满</td><td>降到每天 20 分钟，只做一个动作</td></tr><tr><td>用虚构例子练习</td><td>舍不得真实任务</td><td>用序章任务种子，越真实越有收获</td></tr><tr><td>手册写完就压箱底</td><td>没接入日常</td><td>把手册放桌面/常用位置，每天打开</td></tr><tr><td>第 4 周发现零件缺失</td><td>前几周偷懒了</td><td>回到对应章节补课，不要跳级</td></tr></tbody></table><h2 id="安全提醒" tabindex="-1">安全提醒 <a class="header-anchor" href="#安全提醒" aria-label="Permalink to &quot;安全提醒&quot;">​</a></h2><ul><li>30 天里所有任务先过第 2 章检查表：涉及钱、隐私、对外发布的，不自动执行；</li><li>每周末检查一遍权限卡与备份是否到位（第 8 章）；</li><li>手册 1.0 里如果写了密钥/账号，立即删除（规则文件会被反复读取，第 14 章）。</li></ul><h2 id="本章练习-也是你的最终练习" tabindex="-1">本章练习（也是你的最终练习） <a class="header-anchor" href="#本章练习-也是你的最终练习" aria-label="Permalink to &quot;本章练习（也是你的最终练习）&quot;">​</a></h2><p>30 天，按路线图执行。<strong>本周只做第 1 周计划</strong>：读两章、画流程图、写需求卡、选产品、跑第一个任务。完成后回来更新手册。</p><h2 id="你应该带走的成果" tabindex="-1">你应该带走的成果 <a class="header-anchor" href="#你应该带走的成果" aria-label="Permalink to &quot;你应该带走的成果&quot;">​</a></h2><ul><li><strong>个人 Agent 使用手册 1.0</strong>：任务卡、权限表、验收清单、模板、Skill、协作约定、Harness 设计表、复盘记录——本书全部「应带走成果」的汇总。</li></ul><h2 id="本章小结-全书总结" tabindex="-1">本章小结（全书总结） <a class="header-anchor" href="#本章小结-全书总结" aria-label="Permalink to &quot;本章小结（全书总结）&quot;">​</a></h2><ol><li>认识 Agent（第 1–3 章）：它会干活，也会犯错；人定目标，Agent 执行，人验收；</li><li>选择 Agent（第 4–6 章）：先过滤能不能用，再按任务选；没有全能第一名；</li><li>完成任务（第 7–10 章）：任务卡 → 安全边界 → 过程跟进 → 验收复盘，一次完整闭环；</li><li>稳定工作流（第 11–14 章）：上下文、模板、Skill、规则记忆，把经验变成资产；</li><li>搭建系统（第 15–18 章）：六层 Harness，小步演进，持续可靠；</li><li>真实案例与 30 天计划（第 19–23 章）：从读到做，从做到系统。</li></ol><p><strong>教程到此结束，你的实践才刚刚开始。</strong> 30 天后，欢迎带着你的手册 1.0 回来——那才是这套教程真正的毕业作品。</p>',34)])])}const u=d(l,[["render",i]]);export{g as __pageData,u as default};
